FUN_OBTENER_ALERTAS_JSON:
CREATE OR REPLACE FUNCTION FUN_OBTENER_ALERTAS_JSON(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jFECHA DATE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jHOY DATE;
    jDIAS_GESTACION INTEGER;
    jDIAS_AVISO_PARTO INTEGER;
    jDIAS_PALPAR INTEGER;
    jDIAS_VACIA INTEGER;
    jDIAS_AVISO_VACUNA INTEGER;
    LISTA_PARTOS JSON;
    LISTA_PALPAR JSON;
    LISTA_VACIAS JSON;
    LISTA_VACUNAS JSON;
    LISTA_RETIROS JSON;
    LISTA_CICLOS JSON;
BEGIN
    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --DIAS DE LA CONFIGURACION (CON EL VALOR DE FABRICA SI NO ESTA)
    jHOY := COALESCE(jFECHA, CURRENT_DATE);
    jDIAS_GESTACION := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_GESTACION'), 283)::INTEGER;
    jDIAS_AVISO_PARTO := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_AVISO_PARTO'), 30)::INTEGER;
    jDIAS_PALPAR := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_PALPAR_DESPUES_SERVICIO'), 45)::INTEGER;
    jDIAS_VACIA := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_VACIA_ALERTA'), 120)::INTEGER;
    jDIAS_AVISO_VACUNA := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_AVISO_VACUNA'), 15)::INTEGER;

    --PARTOS PROXIMOS: POR EL ULTIMO SERVICIO (SIN PALPACION VACIA DESPUES) O, SI NO HAY SERVICIO, POR LA ULTIMA PALPACION PREÑADA
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'FECHA_PARTO_PROBABLE', T.FECHA_PROBABLE, 'DIAS', T.FECHA_PROBABLE - jHOY, 'SEGUN', T.SEGUN, 'PADRE', T.PADRE
    ) ORDER BY T.FECHA_PROBABLE, T.CHAPETA_ANIMAL) INTO LISTA_PARTOS
    FROM (
        SELECT A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL,
            CASE WHEN S.FECHA_EVENTO IS NOT NULL THEN S.FECHA_EVENTO::DATE + jDIAS_GESTACION
                 ELSE (P.FECHA_EVENTO + make_interval(months => 9 - P.MESES_GESTACION))::DATE END AS FECHA_PROBABLE,
            CASE WHEN S.FECHA_EVENTO IS NOT NULL THEN 'SERVICIO' ELSE 'PALPACION' END AS SEGUN,
            COALESCE(TORO.CHAPETA_ANIMAL, TORO.NOM_ANIMAL, S.TORO_EXTERNO) AS PADRE
        FROM TAB_ANIMALES A
        LEFT JOIN LATERAL (SELECT MAX(FECHA_EVENTO) AS F FROM TAB_PARTOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PARTO = 'ACTIVO') UP ON true
        LEFT JOIN LATERAL (SELECT * FROM TAB_SERVICIOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_SERVICIO = 'ACTIVO'
                           AND FECHA_EVENTO > COALESCE(UP.F, '-infinity') ORDER BY FECHA_EVENTO DESC LIMIT 1) S ON true
        LEFT JOIN TAB_ANIMALES TORO ON TORO.ID_ANIMAL = S.ID_TORO
        LEFT JOIN LATERAL (SELECT * FROM TAB_PALPACIONES WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PALPACION = 'ACTIVO'
                           AND FECHA_EVENTO > COALESCE(S.FECHA_EVENTO, UP.F, '-infinity') ORDER BY FECHA_EVENTO DESC LIMIT 1) P ON true
        WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO' AND A.SEXO_ANIMAL = 'H'
          AND ((S.FECHA_EVENTO IS NOT NULL AND COALESCE(P.RESULTADO_PALPACION, 'PRENIADA') = 'PRENIADA')
               OR (S.FECHA_EVENTO IS NULL AND P.RESULTADO_PALPACION = 'PRENIADA'))
    ) T
    WHERE T.FECHA_PROBABLE BETWEEN jHOY - 30 AND jHOY + jDIAS_AVISO_PARTO;

    --PALPAR: SERVIDAS HACE DIAS_PALPAR O MAS Y SIN PALPACION DESPUES DEL SERVICIO
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'FECHA_SERVICIO', T.FECHA_SERVICIO, 'DIAS_DESDE_SERVICIO', jHOY - T.FECHA_SERVICIO
    ) ORDER BY T.FECHA_SERVICIO, T.CHAPETA_ANIMAL) INTO LISTA_PALPAR
    FROM (
        SELECT A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL, S.FECHA_EVENTO::DATE AS FECHA_SERVICIO
        FROM TAB_ANIMALES A
        LEFT JOIN LATERAL (SELECT MAX(FECHA_EVENTO) AS F FROM TAB_PARTOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PARTO = 'ACTIVO') UP ON true
        JOIN LATERAL (SELECT * FROM TAB_SERVICIOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_SERVICIO = 'ACTIVO'
                      AND FECHA_EVENTO > COALESCE(UP.F, '-infinity') ORDER BY FECHA_EVENTO DESC LIMIT 1) S ON true
        WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO' AND A.SEXO_ANIMAL = 'H'
          AND S.FECHA_EVENTO::DATE <= jHOY - jDIAS_PALPAR
          AND NOT EXISTS (SELECT 1 FROM TAB_PALPACIONES PA WHERE PA.ID_ANIMAL = A.ID_ANIMAL AND PA.ESTADO_PALPACION = 'ACTIVO' AND PA.FECHA_EVENTO > S.FECHA_EVENTO)
    ) T;

    --VACIAS: VACAS CON EL ULTIMO PARTO HACE MAS DE DIAS_VACIA, SIN SERVICIO DESPUES (O CON LA ULTIMA PALPACION VACIA Y SIN SERVICIO DESPUES DE ELLA)
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'FECHA_ULTIMO_PARTO', T.ULTIMO_PARTO, 'DIAS_VACIA', jHOY - T.ULTIMO_PARTO
    ) ORDER BY T.ULTIMO_PARTO, T.CHAPETA_ANIMAL) INTO LISTA_VACIAS
    FROM (
        SELECT A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL, UP.F::DATE AS ULTIMO_PARTO
        FROM TAB_ANIMALES A
        JOIN LATERAL (SELECT MAX(FECHA_EVENTO) AS F FROM TAB_PARTOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PARTO = 'ACTIVO') UP ON UP.F IS NOT NULL
        LEFT JOIN LATERAL (SELECT * FROM TAB_SERVICIOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_SERVICIO = 'ACTIVO'
                           AND FECHA_EVENTO > UP.F ORDER BY FECHA_EVENTO DESC LIMIT 1) S ON true
        LEFT JOIN LATERAL (SELECT * FROM TAB_PALPACIONES WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PALPACION = 'ACTIVO'
                           AND FECHA_EVENTO > UP.F ORDER BY FECHA_EVENTO DESC LIMIT 1) P ON true
        WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO' AND A.SEXO_ANIMAL = 'H'
          AND UP.F::DATE < jHOY - jDIAS_VACIA
          AND COALESCE(P.RESULTADO_PALPACION, '') <> 'PRENIADA'
          AND (S.FECHA_EVENTO IS NULL OR (P.RESULTADO_PALPACION = 'VACIA' AND P.FECHA_EVENTO > S.FECHA_EVENTO))
    ) T;

    --VACUNAS POR APLICAR: LA ULTIMA APLICACION DE CADA PRODUCTO A CADA ANIMAL, CON SU PROXIMA DOSIS DENTRO DEL AVISO (O ATRASADA HASTA 30 DIAS)
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'ID_VACUNA', T.ID_VACUNA, 'NOM_VACUNA', T.NOM_VACUNA, 'FECHA_PROXIMA_DOSIS', T.FECHA_PROXIMA_DOSIS, 'DIAS', T.FECHA_PROXIMA_DOSIS - jHOY
    ) ORDER BY T.FECHA_PROXIMA_DOSIS, T.NOM_VACUNA, T.CHAPETA_ANIMAL) INTO LISTA_VACUNAS
    FROM (
        SELECT DISTINCT ON (VC.ID_ANIMAL, VC.ID_VACUNA) A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL, V.ID_VACUNA, V.NOM_VACUNA, VC.FECHA_PROXIMA_DOSIS
        FROM TAB_VACUNACIONES VC
        JOIN TAB_ANIMALES A ON A.ID_ANIMAL = VC.ID_ANIMAL
        JOIN TAB_VACUNAS V ON V.ID_VACUNA = VC.ID_VACUNA
        WHERE VC.ID_FINCA = jID_FINCA AND VC.ESTADO_VACUNACION = 'ACTIVO' AND A.ESTADO_ANIMAL = 'ACTIVO'
        ORDER BY VC.ID_ANIMAL, VC.ID_VACUNA, VC.FECHA_EVENTO DESC
    ) T
    WHERE T.FECHA_PROXIMA_DOSIS BETWEEN jHOY - 30 AND jHOY + jDIAS_AVISO_VACUNA;

    --RETIROS DE LECHE VIGENTES: NO VENDER LA LECHE DE ESTOS ANIMALES HASTA LA FECHA
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'NOM_VACUNA', T.NOM_VACUNA, 'FECHA_FIN_RETIRO', T.FECHA_FIN_RETIRO, 'DIAS_RESTANTES', T.FECHA_FIN_RETIRO - jHOY
    ) ORDER BY T.FECHA_FIN_RETIRO DESC, T.CHAPETA_ANIMAL) INTO LISTA_RETIROS
    FROM (
        SELECT DISTINCT ON (VC.ID_ANIMAL) A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL, V.NOM_VACUNA, VC.FECHA_FIN_RETIRO
        FROM TAB_VACUNACIONES VC
        JOIN TAB_ANIMALES A ON A.ID_ANIMAL = VC.ID_ANIMAL
        JOIN TAB_VACUNAS V ON V.ID_VACUNA = VC.ID_VACUNA
        WHERE VC.ID_FINCA = jID_FINCA AND VC.ESTADO_VACUNACION = 'ACTIVO' AND A.ESTADO_ANIMAL = 'ACTIVO'
          AND VC.FECHA_FIN_RETIRO >= jHOY AND VC.FECHA_EVENTO::DATE <= jHOY
        ORDER BY VC.ID_ANIMAL, VC.FECHA_FIN_RETIRO DESC
    ) T;

    --CICLOS DEL ICA VIGENTES O QUE EMPIEZAN EN 30 DIAS, CON LOS ANIMALES ACTIVOS QUE AUN NO TIENEN ESA VACUNA EN EL CICLO
    SELECT json_agg(json_build_object(
        'ID_CICLO', C.ID_CICLO, 'NOM_CICLO', C.NOM_CICLO, 'NOM_VACUNA', V.NOM_VACUNA,
        'FECHA_INICIO_CICLO', C.FECHA_INICIO_CICLO, 'FECHA_FIN_CICLO', C.FECHA_FIN_CICLO,
        'VIGENTE', jHOY BETWEEN C.FECHA_INICIO_CICLO AND C.FECHA_FIN_CICLO,
        'DIAS_PARA_EMPEZAR', GREATEST(C.FECHA_INICIO_CICLO - jHOY, 0), 'DIAS_PARA_TERMINAR', C.FECHA_FIN_CICLO - jHOY,
        'FALTAN', (SELECT COUNT(*) FROM TAB_ANIMALES A
                   WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO'
                     AND NOT EXISTS (SELECT 1 FROM TAB_VACUNACIONES VC WHERE VC.ID_ANIMAL = A.ID_ANIMAL AND VC.ID_VACUNA = C.ID_VACUNA
                                     AND VC.ESTADO_VACUNACION = 'ACTIVO' AND VC.FECHA_EVENTO::DATE BETWEEN C.FECHA_INICIO_CICLO AND C.FECHA_FIN_CICLO))
    ) ORDER BY C.FECHA_INICIO_CICLO) INTO LISTA_CICLOS
    FROM TAB_CICLOS_ICA C
    JOIN TAB_VACUNAS V ON V.ID_VACUNA = C.ID_VACUNA
    WHERE C.ESTADO_CICLO = 'ACTIVO' AND C.FECHA_FIN_CICLO >= jHOY AND C.FECHA_INICIO_CICLO <= jHOY + 30;

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Alertas de la finca',
        'DATOS', json_build_object(
            'FECHA', jHOY,
            'PARTOS_PROXIMOS', COALESCE(LISTA_PARTOS, '[]'::JSON),
            'PALPAR', COALESCE(LISTA_PALPAR, '[]'::JSON),
            'VACIAS', COALESCE(LISTA_VACIAS, '[]'::JSON),
            'VACUNAS_POR_APLICAR', COALESCE(LISTA_VACUNAS, '[]'::JSON),
            'RETIROS_LECHE', COALESCE(LISTA_RETIROS, '[]'::JSON),
            'CICLOS_ICA', COALESCE(LISTA_CICLOS, '[]'::JSON),
            'DIAS_VACIA_ALERTA', jDIAS_VACIA,
            'DIAS_AVISO_PARTO', jDIAS_AVISO_PARTO));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;

FUN_OBTENER_ANIMALES_JSON:
CREATE OR REPLACE FUNCTION FUN_OBTENER_ANIMALES_JSON(
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jESTADO VARCHAR,
    jID_USUARIO TAB_ANIMALES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    LISTA_ANIMALES JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT json_agg(FUN_DATOS_ANIMAL(ID_ANIMAL) ORDER BY ESTADO_ANIMAL, CHAPETA_ANIMAL NULLS LAST, NOM_ANIMAL) INTO LISTA_ANIMALES
    FROM TAB_ANIMALES
    WHERE ID_FINCA = jID_FINCA
      AND ESTADO_ANIMAL <> 'ANULADO'
      AND (COALESCE(jESTADO, 'ACTIVO') = 'TODOS' OR ESTADO_ANIMAL = 'ACTIVO');

    IF LISTA_ANIMALES IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Todavía no hay animales registrados');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Animales de la finca', 'DATOS', LISTA_ANIMALES);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;

FUN_OBTENER_MIS_FINCAS_JSON:
CREATE OR REPLACE FUNCTION FUN_OBTENER_MIS_FINCAS_JSON(
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    LISTA_FINCAS JSON;
BEGIN
    SELECT json_agg(json_build_object(
        'ID_FINCA', F.ID_FINCA,
        'NOM_FINCA', F.NOM_FINCA,
        'MUNICIPIO_FINCA', F.MUNICIPIO_FINCA,
        'VEREDA_FINCA', F.VEREDA_FINCA,
        'ROL_FINCA', P.ROL_FINCA,
        'ANIMALES_ACTIVOS', (SELECT COUNT(*) FROM TAB_ANIMALES A WHERE A.ID_FINCA = F.ID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO')
    ) ORDER BY F.NOM_FINCA) INTO LISTA_FINCAS
    FROM TAB_FINCAS_PERSONAS P
    JOIN TAB_FINCAS F ON F.ID_FINCA = P.ID_FINCA
    WHERE P.ID_USUARIO = jID_USUARIO
      AND P.ESTADO_FINCA_PERSONA = 'ACTIVO'
      AND F.ESTADO_FINCA = 'ACTIVO';

    IF LISTA_FINCAS IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Todavía no trabajas en ninguna finca');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Tus fincas', 'DATOS', LISTA_FINCAS);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;

FUN_OBTENER_INDICADORES_JSON:
CREATE OR REPLACE FUNCTION FUN_OBTENER_INDICADORES_JSON(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jDESDE DATE,
    jHASTA DATE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jFIN DATE;
    jINICIO DATE;
    jPRESENTES INTEGER;
    jHEMBRAS INTEGER;
    jCRIAS_VIVAS INTEGER;
    jMUERTES INTEGER;
    jINTERVALO NUMERIC;
    jINTERVALOS INTEGER;
    jLITROS NUMERIC;
    jDIAS_ORDENO INTEGER;
    jLITROS_VACA_DIA NUMERIC;
    jVENTAS INTEGER;
    jVALOR_VENTAS NUMERIC;
    jGDP_GENERAL NUMERIC;
    jGDP_ANIMALES INTEGER;
    LISTA_CATEGORIAS JSON;
    LISTA_LECHE_MES JSON;
    LISTA_PARTOS_MES JSON;
    LISTA_GDP_LOTE JSON;
BEGIN
    --VALIDAR EL ACCESO (DUEÑO Y VETERINARIO)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO', 'VETERINARIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --EL PERIODO
    jFIN := COALESCE(jHASTA, CURRENT_DATE);
    jINICIO := COALESCE(jDESDE, (jFIN - INTERVAL '12 months')::DATE + 1);
    IF jINICIO > jFIN THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha inicial debe ser antes de la final');
        RETURN RETORNO;
    ELSIF jFIN - jINICIO > 1100 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El periodo puede ser de máximo 3 años');
        RETURN RETORNO;
    END IF;

    --ANIMALES QUE ESTUVIERON EN LA FINCA EN EL PERIODO
    SELECT COUNT(*) INTO jPRESENTES
    FROM TAB_ANIMALES A
    WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL <> 'ANULADO'
      AND A.FECHA_INGRESO_ANIMAL <= jFIN AND COALESCE(A.FECHA_SALIDA_ANIMAL::DATE, 'infinity') >= jINICIO;

    --HEMBRAS REPRODUCTORAS QUE ESTUVIERON (24 MESES O MAS AL FINAL DEL PERIODO, O CON ALGUN PARTO)
    SELECT COUNT(*) INTO jHEMBRAS
    FROM TAB_ANIMALES A
    WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL <> 'ANULADO' AND A.SEXO_ANIMAL = 'H'
      AND A.FECHA_INGRESO_ANIMAL <= jFIN AND COALESCE(A.FECHA_SALIDA_ANIMAL::DATE, 'infinity') >= jINICIO
      AND (A.FECHA_NACIMIENTO <= (jFIN - INTERVAL '24 months')::DATE
           OR EXISTS (SELECT 1 FROM TAB_PARTOS P WHERE P.ID_ANIMAL = A.ID_ANIMAL AND P.ESTADO_PARTO = 'ACTIVO' AND P.FECHA_EVENTO::DATE <= jFIN));

    --CRIAS VIVAS Y MUERTES EN EL PERIODO
    SELECT COUNT(*) INTO jCRIAS_VIVAS FROM TAB_PARTOS
    WHERE ID_FINCA = jID_FINCA AND ESTADO_PARTO = 'ACTIVO' AND CRIA_VIVA = 'SI' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN;
    SELECT COUNT(*) INTO jMUERTES FROM TAB_SALIDAS
    WHERE ID_FINCA = jID_FINCA AND ESTADO_SALIDA = 'ACTIVO' AND TIPO_SALIDA = 'MUERTE' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN;

    --INTERVALO ENTRE PARTOS: CADA PARTO DEL PERIODO CONTRA EL PARTO ANTERIOR DE LA MISMA VACA
    SELECT AVG(T.DIAS), COUNT(*) INTO jINTERVALO, jINTERVALOS
    FROM (
        SELECT P.FECHA_EVENTO::DATE - (SELECT MAX(Q.FECHA_EVENTO)::DATE FROM TAB_PARTOS Q
                                       WHERE Q.ID_ANIMAL = P.ID_ANIMAL AND Q.ESTADO_PARTO = 'ACTIVO' AND Q.FECHA_EVENTO < P.FECHA_EVENTO) AS DIAS
        FROM TAB_PARTOS P
        WHERE P.ID_FINCA = jID_FINCA AND P.ESTADO_PARTO = 'ACTIVO' AND P.FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
    ) T
    WHERE T.DIAS IS NOT NULL;

    --LECHE: TOTAL, DIAS CON ORDEÑO Y LITROS POR VACA AL DIA
    SELECT SUM(T.LITROS), COUNT(*), AVG(T.LITROS / T.VACAS) INTO jLITROS, jDIAS_ORDENO, jLITROS_VACA_DIA
    FROM (
        SELECT FECHA_EVENTO::DATE AS DIA, SUM(LITROS_ORDENO) AS LITROS, COUNT(DISTINCT ID_ANIMAL) AS VACAS
        FROM TAB_ORDENOS
        WHERE ID_FINCA = jID_FINCA AND ESTADO_ORDENO = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
        GROUP BY FECHA_EVENTO::DATE
    ) T;

    --LECHE POR MES (PARA LA GRAFICA)
    SELECT json_agg(json_build_object('MES', T.MES, 'LITROS', T.LITROS, 'LITROS_VACA_DIA', round(T.LVD, 1)) ORDER BY T.MES) INTO LISTA_LECHE_MES
    FROM (
        SELECT to_char(D.DIA, 'YYYY-MM') AS MES, SUM(D.LITROS) AS LITROS, AVG(D.LITROS / D.VACAS) AS LVD
        FROM (
            SELECT FECHA_EVENTO::DATE AS DIA, SUM(LITROS_ORDENO) AS LITROS, COUNT(DISTINCT ID_ANIMAL) AS VACAS
            FROM TAB_ORDENOS
            WHERE ID_FINCA = jID_FINCA AND ESTADO_ORDENO = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
            GROUP BY FECHA_EVENTO::DATE
        ) D
        GROUP BY to_char(D.DIA, 'YYYY-MM')
    ) T;

    --PARTOS POR MES (PARA LA GRAFICA)
    SELECT json_agg(json_build_object('MES', T.MES, 'PARTOS', T.PARTOS, 'CRIAS_VIVAS', T.VIVAS) ORDER BY T.MES) INTO LISTA_PARTOS_MES
    FROM (
        SELECT to_char(FECHA_EVENTO, 'YYYY-MM') AS MES, COUNT(*) AS PARTOS, COUNT(*) FILTER (WHERE CRIA_VIVA = 'SI') AS VIVAS
        FROM TAB_PARTOS
        WHERE ID_FINCA = jID_FINCA AND ESTADO_PARTO = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
        GROUP BY to_char(FECHA_EVENTO, 'YYYY-MM')
    ) T;

    --GANANCIA DIARIA DE PESO: POR ANIMAL (PRIMER Y ULTIMO PESAJE DEL PERIODO, AL MENOS 14 DIAS ENTRE ELLOS) Y PROMEDIO POR LOTE
    SELECT json_agg(json_build_object('NOM_LOTE', T.NOM_LOTE, 'ANIMALES', T.ANIMALES, 'GRAMOS_DIA', round(T.GRAMOS)) ORDER BY T.NOM_LOTE) INTO LISTA_GDP_LOTE
    FROM (
        SELECT COALESCE(L.NOM_LOTE, 'Sin lote') AS NOM_LOTE, COUNT(*) AS ANIMALES, AVG(G.GRAMOS) AS GRAMOS
        FROM (
            SELECT P1.ID_ANIMAL, (P2.PESO_KG - P1.PESO_KG) * 1000 / (P2.FECHA_EVENTO::DATE - P1.FECHA_EVENTO::DATE) AS GRAMOS
            FROM (SELECT DISTINCT ON (ID_ANIMAL) ID_ANIMAL, PESO_KG, FECHA_EVENTO FROM TAB_PESAJES
                  WHERE ID_FINCA = jID_FINCA AND ESTADO_PESAJE = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
                  ORDER BY ID_ANIMAL, FECHA_EVENTO ASC) P1
            JOIN (SELECT DISTINCT ON (ID_ANIMAL) ID_ANIMAL, PESO_KG, FECHA_EVENTO FROM TAB_PESAJES
                  WHERE ID_FINCA = jID_FINCA AND ESTADO_PESAJE = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
                  ORDER BY ID_ANIMAL, FECHA_EVENTO DESC) P2 ON P2.ID_ANIMAL = P1.ID_ANIMAL
            WHERE P2.FECHA_EVENTO::DATE - P1.FECHA_EVENTO::DATE >= 14
        ) G
        JOIN TAB_ANIMALES A ON A.ID_ANIMAL = G.ID_ANIMAL
        LEFT JOIN TAB_LOTES L ON L.ID_LOTE = A.ID_LOTE
        GROUP BY COALESCE(L.NOM_LOTE, 'Sin lote')
    ) T;

    SELECT AVG(G.GRAMOS), COUNT(*) INTO jGDP_GENERAL, jGDP_ANIMALES
    FROM (
        SELECT (P2.PESO_KG - P1.PESO_KG) * 1000 / (P2.FECHA_EVENTO::DATE - P1.FECHA_EVENTO::DATE) AS GRAMOS
        FROM (SELECT DISTINCT ON (ID_ANIMAL) ID_ANIMAL, PESO_KG, FECHA_EVENTO FROM TAB_PESAJES
              WHERE ID_FINCA = jID_FINCA AND ESTADO_PESAJE = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
              ORDER BY ID_ANIMAL, FECHA_EVENTO ASC) P1
        JOIN (SELECT DISTINCT ON (ID_ANIMAL) ID_ANIMAL, PESO_KG, FECHA_EVENTO FROM TAB_PESAJES
              WHERE ID_FINCA = jID_FINCA AND ESTADO_PESAJE = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
              ORDER BY ID_ANIMAL, FECHA_EVENTO DESC) P2 ON P2.ID_ANIMAL = P1.ID_ANIMAL
        WHERE P2.FECHA_EVENTO::DATE - P1.FECHA_EVENTO::DATE >= 14
    ) G;

    --VENTAS DEL PERIODO
    SELECT COUNT(*), COALESCE(SUM(VALOR_SALIDA), 0) INTO jVENTAS, jVALOR_VENTAS FROM TAB_SALIDAS
    WHERE ID_FINCA = jID_FINCA AND ESTADO_SALIDA = 'ACTIVO' AND TIPO_SALIDA = 'VENTA' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN;

    --EL HATO DE HOY POR CATEGORIA
    SELECT json_agg(json_build_object('CATEGORIA', T.CATEGORIA, 'CANTIDAD', T.CANTIDAD) ORDER BY T.ORDEN) INTO LISTA_CATEGORIAS
    FROM (
        SELECT FUN_CATEGORIA_ANIMAL(ID_ANIMAL) AS CATEGORIA, COUNT(*) AS CANTIDAD,
            array_position(ARRAY['VACA', 'NOVILLA', 'TERNERA', 'TORO', 'NOVILLO', 'TERNERO']::VARCHAR[], FUN_CATEGORIA_ANIMAL(ID_ANIMAL)) AS ORDEN
        FROM TAB_ANIMALES
        WHERE ID_FINCA = jID_FINCA AND ESTADO_ANIMAL = 'ACTIVO'
        GROUP BY FUN_CATEGORIA_ANIMAL(ID_ANIMAL)
    ) T;

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Indicadores de la finca',
        'DATOS', json_build_object(
            'DESDE', jINICIO,
            'HASTA', jFIN,
            'ANIMALES_EN_EL_PERIODO', jPRESENTES,
            'HATO_POR_CATEGORIA', COALESCE(LISTA_CATEGORIAS, '[]'::JSON),
            'NATALIDAD', json_build_object('CRIAS_VIVAS', jCRIAS_VIVAS, 'HEMBRAS', jHEMBRAS,
                'PORCENTAJE', CASE WHEN jHEMBRAS > 0 THEN round(jCRIAS_VIVAS * 100.0 / jHEMBRAS, 1) END),
            'MORTALIDAD', json_build_object('MUERTES', jMUERTES, 'ANIMALES', jPRESENTES,
                'PORCENTAJE', CASE WHEN jPRESENTES > 0 THEN round(jMUERTES * 100.0 / jPRESENTES, 1) END),
            'INTERVALO_PARTOS', json_build_object('PROMEDIO_DIAS', round(jINTERVALO), 'INTERVALOS', COALESCE(jINTERVALOS, 0)),
            'LECHE', json_build_object('LITROS_TOTALES', COALESCE(jLITROS, 0), 'DIAS_CON_ORDENO', COALESCE(jDIAS_ORDENO, 0),
                'LITROS_VACA_DIA', round(jLITROS_VACA_DIA, 1), 'POR_MES', COALESCE(LISTA_LECHE_MES, '[]'::JSON)),
            'PARTOS_POR_MES', COALESCE(LISTA_PARTOS_MES, '[]'::JSON),
            'GANANCIA_PESO', json_build_object('GRAMOS_DIA', round(jGDP_GENERAL), 'ANIMALES', COALESCE(jGDP_ANIMALES, 0),
                'POR_LOTE', COALESCE(LISTA_GDP_LOTE, '[]'::JSON)),
            'VENTAS', json_build_object('CANTIDAD', jVENTAS, 'VALOR_TOTAL', jVALOR_VENTAS)));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;

FUN_CREAR_PESAJE_JSON:
CREATE OR REPLACE FUNCTION FUN_CREAR_PESAJE_JSON(
    jUUID_PESAJE TAB_PESAJES.UUID_PESAJE%TYPE,
    jID_FINCA TAB_PESAJES.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jPESO_KG TAB_PESAJES.PESO_KG%TYPE,
    jESTIMADO_CINTA TAB_PESAJES.ESTIMADO_CINTA%TYPE,
    jPERIMETRO_CM TAB_PESAJES.PERIMETRO_CM%TYPE,
    jFECHA_EVENTO TAB_PESAJES.FECHA_EVENTO%TYPE,
    jOBSERVACION TAB_PESAJES.OBSERVACION_PESAJE%TYPE,
    jID_USUARIO TAB_PESAJES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_PESAJE INTEGER;
    jID_ANIMAL INTEGER;
    jPESO NUMERIC;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_PESAJE INTO jID_PESAJE FROM TAB_PESAJES WHERE UUID_PESAJE = jUUID_PESAJE;
    IF jID_PESAJE IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El pesaje ya estaba guardado',
            'DATOS', json_build_object('ID_PESAJE', jID_PESAJE, 'UUID_PESAJE', jUUID_PESAJE, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_PESAJE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del pesaje');
        RETURN RETORNO;
    END IF;

    --TRADUCIR EL ANIMAL Y CALCULAR EL PESO CON CINTA SI NO VINO
    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    jPESO := CASE WHEN jESTIMADO_CINTA = 'SI' AND jPESO_KG IS NULL THEN FUN_PESO_POR_CINTA(jPERIMETRO_CM) ELSE jPESO_KG END;

    --LLAMAR A LA FUNCION DE VALIDACION
    jVALIDACION := FUN_VALIDAR_PESAJES(jID_ANIMAL, jFECHA_EVENTO, jPESO, COALESCE(jESTIMADO_CINTA, 'NO'), jPERIMETRO_CM, jOBSERVACION);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --INSERTAR EL PESAJE (EL TRIGGER TRG_PESO_ACTUAL ACTUALIZA EL PESO DEL ANIMAL)
    jID_PESAJE := funcion_Retorna_ultmoid('TAB_PESAJES', 'ID_PESAJE');
    INSERT INTO TAB_PESAJES (ID_PESAJE, UUID_PESAJE, ID_FINCA, ID_ANIMAL, FECHA_EVENTO, PESO_KG, ESTIMADO_CINTA, PERIMETRO_CM, OBSERVACION_PESAJE, USUARIO_CREACION)
    VALUES (jID_PESAJE, jUUID_PESAJE, jID_FINCA, jID_ANIMAL, jFECHA_EVENTO, jPESO, COALESCE(jESTIMADO_CINTA, 'NO'),
        CASE WHEN jESTIMADO_CINTA = 'SI' THEN jPERIMETRO_CM END, NULLIF(TRIM(jOBSERVACION), ''), jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Pesaje guardado: ' || trim(to_char(jPESO, 'FM9990.0')) || ' kg',
            'DATOS', json_build_object('ID_PESAJE', jID_PESAJE, 'UUID_PESAJE', jUUID_PESAJE, 'PESO_KG', jPESO, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al guardar el pesaje');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;

FUN_VALIDAR_PESAJES:
CREATE OR REPLACE FUNCTION FUN_VALIDAR_PESAJES(
    jID_ANIMAL TAB_PESAJES.ID_ANIMAL%TYPE,
    jFECHA_EVENTO TAB_PESAJES.FECHA_EVENTO%TYPE,
    jPESO_KG TAB_PESAJES.PESO_KG%TYPE,
    jESTIMADO_CINTA TAB_PESAJES.ESTIMADO_CINTA%TYPE,
    jPERIMETRO_CM TAB_PESAJES.PERIMETRO_CM%TYPE,
    jOBSERVACION TAB_PESAJES.OBSERVACION_PESAJE%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    --LO COMUN A TODOS LOS EVENTOS (ANIMAL Y FECHA)
    RETORNO := FUN_VALIDAR_EVENTO_ANIMAL(jID_ANIMAL, jFECHA_EVENTO);
    IF (RETORNO ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN RETORNO;

    --VALIDACION VARIABLE ESTIMADO_CINTA Y PERIMETRO_CM
    ELSIF jESTIMADO_CINTA IS NULL OR jESTIMADO_CINTA NOT IN ('SI', 'NO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Indica si el peso es con báscula o con cinta');
        RETURN RETORNO;
    ELSIF jESTIMADO_CINTA = 'SI' AND (jPERIMETRO_CM IS NULL OR jPERIMETRO_CM < 50 OR jPERIMETRO_CM > 300) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Con cinta, escribe el perímetro del pecho en centímetros (de 50 a 300)');
        RETURN RETORNO;

    --VALIDACION VARIABLE PESO_KG
    ELSIF jPESO_KG IS NULL OR jPESO_KG <= 0 OR jPESO_KG > 1500 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe un peso entre 1 y 1500 kilos');
        RETURN RETORNO;

    --VALIDACION VARIABLE OBSERVACION (OPCIONAL)
    ELSIF LENGTH(COALESCE(jOBSERVACION, '')) > 300 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La nota es demasiado larga (máximo 300 caracteres)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;

FUN_SINCRONIZAR_REGISTROS_JSON:
CREATE OR REPLACE FUNCTION FUN_SINCRONIZAR_REGISTROS_JSON(
    jID_FINCA TAB_SINCRONIZACIONES.ID_FINCA%TYPE,
    jID_USUARIO TAB_SINCRONIZACIONES.ID_USUARIO%TYPE,
    jREGISTROS JSON
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jREGISTRO JSON;
    jDATOS JSON;
    jTIPO VARCHAR;
    jOPERACION VARCHAR;
    jUUID UUID;
    jRESULTADO JSON;
    jESTADO VARCHAR;
    jMAXIMO INTEGER;
    jRECIBIDOS INTEGER;
    jGUARDADOS INTEGER := 0;
    jOMITIDOS INTEGER := 0;
    jRECHAZADOS INTEGER := 0;
    LISTA_RESULTADOS JSON[] := ARRAY[]::JSON[];
    LISTA_RECHAZADOS JSON[] := ARRAY[]::JSON[];
    jID_SINCRONIZACION INTEGER;
BEGIN
    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA; CADA FUNCION REVISA DESPUES SU PROPIO PERMISO)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --VALIDAR EL LOTE
    jMAXIMO := COALESCE(FUN_CONFIGURACION_NUMERO('LOTE_MAXIMO_SINCRONIZACION'), 50)::INTEGER;
    IF jREGISTROS IS NULL OR json_typeof(jREGISTROS) <> 'array' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Los registros deben llegar en una lista');
        RETURN RETORNO;
    END IF;
    jRECIBIDOS := json_array_length(jREGISTROS);
    IF jRECIBIDOS = 0 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'No hay registros para subir');
        RETURN RETORNO;
    ELSIF jRECIBIDOS > jMAXIMO THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Máximo ' || jMAXIMO || ' registros por envío');
        RETURN RETORNO;
    END IF;

    --RECORRER LOS REGISTROS EN EL ORDEN EN QUE LLEGARON (UN ANIMAL CREADO SIN SEÑAL LLEGA ANTES QUE SUS EVENTOS)
    FOR jREGISTRO IN SELECT R.value FROM json_array_elements(jREGISTROS) WITH ORDINALITY AS R(value, posicion) ORDER BY R.posicion LOOP
        jTIPO := UPPER(TRIM(jREGISTRO ->> 'tipo'));
        jOPERACION := UPPER(TRIM(COALESCE(jREGISTRO ->> 'operacion', 'CREAR')));
        jDATOS := COALESCE(jREGISTRO -> 'datos', '{}'::JSON);
        jUUID := NULL;

        BEGIN
            jUUID := NULLIF(jREGISTRO ->> 'uuid', '')::UUID;
            IF jUUID IS NULL THEN
                jRESULTADO := json_build_object('CODIGO', 400, 'MENSAJE', 'El registro no trae UUID');

            --CREAR
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'LOTE' THEN
                jRESULTADO := FUN_CREAR_LOTE_JSON(jUUID, jID_FINCA, jDATOS ->> 'nom_lote', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'ANIMAL' THEN
                jRESULTADO := FUN_CREAR_ANIMAL_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_lote', '')::UUID, (jDATOS ->> 'id_raza')::INTEGER,
                    jDATOS ->> 'chapeta_animal', jDATOS ->> 'nom_animal', jDATOS ->> 'sexo_animal', (jDATOS ->> 'fecha_nacimiento')::DATE,
                    jDATOS ->> 'fecha_nacimiento_estimada', NULLIF(jDATOS ->> 'uuid_madre', '')::UUID, NULLIF(jDATOS ->> 'uuid_padre', '')::UUID,
                    jDATOS ->> 'padre_externo', jDATOS ->> 'origen_animal', (jDATOS ->> 'fecha_ingreso_animal')::DATE, jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'PESAJE' THEN
                jRESULTADO := FUN_CREAR_PESAJE_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, (jDATOS ->> 'peso_kg')::NUMERIC,
                    COALESCE(jDATOS ->> 'estimado_cinta', 'NO'), (jDATOS ->> 'perimetro_cm')::NUMERIC, (jDATOS ->> 'fecha_evento')::TIMESTAMP,
                    jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'VACUNACION' THEN
                jRESULTADO := FUN_CREAR_VACUNACION_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, (jDATOS ->> 'id_vacuna')::INTEGER,
                    jDATOS ->> 'dosis_vacunacion', (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'SERVICIO' THEN
                jRESULTADO := FUN_CREAR_SERVICIO_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'tipo_servicio',
                    NULLIF(jDATOS ->> 'uuid_toro', '')::UUID, jDATOS ->> 'toro_externo', (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'PALPACION' THEN
                jRESULTADO := FUN_CREAR_PALPACION_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'resultado_palpacion',
                    (jDATOS ->> 'meses_gestacion')::INTEGER, (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'PARTO' THEN
                jRESULTADO := FUN_CREAR_PARTO_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'tipo_parto', jDATOS ->> 'cria_viva',
                    NULLIF(jDATOS ->> 'uuid_cria', '')::UUID, jDATOS ->> 'sexo_cria', jDATOS ->> 'chapeta_cria', jDATOS ->> 'nom_cria',
                    (jDATOS ->> 'peso_cria_kg')::NUMERIC, (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'ORDENO' THEN
                jRESULTADO := FUN_CREAR_ORDENO_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'jornada_ordeno',
                    (jDATOS ->> 'litros_ordeno')::NUMERIC, (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'SALIDA' THEN
                jRESULTADO := FUN_CREAR_SALIDA_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'tipo_salida',
                    (jDATOS ->> 'valor_salida')::NUMERIC, (jDATOS ->> 'peso_salida_kg')::NUMERIC, jDATOS ->> 'causa_salida',
                    (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'POTRERO' THEN
                jRESULTADO := FUN_CREAR_POTRERO_JSON(jUUID, jID_FINCA, jDATOS ->> 'nom_potrero', (jDATOS ->> 'area_potrero')::NUMERIC,
                    (jDATOS ->> 'dias_descanso_potrero')::INTEGER, jDATOS -> 'contorno_potrero', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'OCUPACION' THEN
                jRESULTADO := FUN_ENTRAR_LOTE_POTRERO_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_lote', '')::UUID, NULLIF(jDATOS ->> 'uuid_potrero', '')::UUID,
                    (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'MOVIMIENTO' THEN
                jRESULTADO := FUN_CREAR_MOVIMIENTO_JSON(jUUID, jID_FINCA, jDATOS ->> 'tipo_movimiento', jDATOS ->> 'categoria_movimiento',
                    (jDATOS ->> 'valor_movimiento')::NUMERIC, (jDATOS ->> 'litros_movimiento')::NUMERIC, jDATOS ->> 'descripcion_movimiento',
                    (jDATOS ->> 'fecha_evento')::TIMESTAMP, jID_USUARIO);

            --EDITAR (GANA EL ULTIMO QUE SINCRONIZA)
            ELSIF jOPERACION = 'EDITAR' AND jTIPO = 'LOTE' THEN
                jRESULTADO := FUN_ACTUALIZAR_LOTE_JSON(jUUID, jID_FINCA, jDATOS ->> 'nom_lote', jID_USUARIO);
            ELSIF jOPERACION = 'EDITAR' AND jTIPO = 'ANIMAL' THEN
                jRESULTADO := FUN_ACTUALIZAR_ANIMAL_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_lote', '')::UUID, (jDATOS ->> 'id_raza')::INTEGER,
                    jDATOS ->> 'chapeta_animal', jDATOS ->> 'nom_animal', jDATOS ->> 'sexo_animal', (jDATOS ->> 'fecha_nacimiento')::DATE,
                    jDATOS ->> 'fecha_nacimiento_estimada', NULLIF(jDATOS ->> 'uuid_madre', '')::UUID, NULLIF(jDATOS ->> 'uuid_padre', '')::UUID,
                    jDATOS ->> 'padre_externo', jDATOS ->> 'origen_animal', (jDATOS ->> 'fecha_ingreso_animal')::DATE, jID_USUARIO);
            ELSIF jOPERACION = 'EDITAR' AND jTIPO = 'POTRERO' THEN
                jRESULTADO := FUN_ACTUALIZAR_POTRERO_JSON(jUUID, jID_FINCA, jDATOS ->> 'nom_potrero', (jDATOS ->> 'area_potrero')::NUMERIC,
                    (jDATOS ->> 'dias_descanso_potrero')::INTEGER, jDATOS -> 'contorno_potrero', jID_USUARIO);
            ELSIF jOPERACION = 'EDITAR' AND jTIPO = 'OCUPACION' THEN
                jRESULTADO := FUN_SACAR_LOTE_POTRERO_JSON(jUUID, jID_FINCA, (jDATOS ->> 'fecha_salida_ocupacion')::TIMESTAMP, jID_USUARIO);

            --ANULAR
            ELSIF jOPERACION = 'ANULAR' AND jTIPO = 'LOTE' THEN
                jRESULTADO := FUN_ANULAR_LOTE_JSON(jUUID, jID_FINCA, jID_USUARIO);
            ELSIF jOPERACION = 'ANULAR' AND jTIPO = 'ANIMAL' THEN
                jRESULTADO := FUN_ANULAR_ANIMAL_JSON(jUUID, jID_FINCA, jID_USUARIO);
            ELSIF jOPERACION = 'ANULAR' AND jTIPO = 'POTRERO' THEN
                jRESULTADO := FUN_ANULAR_POTRERO_JSON(jUUID, jID_FINCA, jID_USUARIO);
            ELSIF jOPERACION = 'ANULAR' AND jTIPO = 'OCUPACION' THEN
                jRESULTADO := FUN_ANULAR_OCUPACION_JSON(jUUID, jID_FINCA, jID_USUARIO);
            ELSIF jOPERACION = 'ANULAR' AND FUN_TABLA_POR_TIPO(jTIPO) IS NOT NULL THEN
                jRESULTADO := FUN_ANULAR_EVENTO_JSON(jTIPO, jUUID, jID_FINCA, jID_USUARIO);

            ELSE
                jRESULTADO := json_build_object('CODIGO', 400, 'MENSAJE', 'Tipo u operación no soportada: ' || COALESCE(jTIPO, '?') || ' ' || jOPERACION);
            END IF;

            --SI LA FUNCION NO GUARDO, SE DESHACE LO QUE HUBIERA HECHO ESTE REGISTRO (SOLO ESTE)
            IF (jRESULTADO ->> 'CODIGO')::INTEGER != 200 THEN
                RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = jRESULTADO ->> 'MENSAJE';
            END IF;
        EXCEPTION
            WHEN unique_violation THEN
                --DOS CELULARES SUBIERON LO MISMO A LA VEZ: EL OTRO YA LO GUARDO (YA_EXISTIA). SI EL CHOQUE FUE CON OTRA REGLA UNICA
                --(POR EJEMPLO LA MISMA JORNADA DE ORDEÑO DESDE DOS CELULARES), SE RECHAZA CON UN MENSAJE CLARO
                IF FUN_EXISTE_UUID(jTIPO, jUUID) THEN
                    jRESULTADO := json_build_object('CODIGO', 200, 'MENSAJE', 'Ya estaba guardado', 'DATOS', json_build_object('YA_EXISTIA', true));
                ELSE
                    jRESULTADO := json_build_object('CODIGO', 400, 'MENSAJE', 'Otro celular guardó lo mismo al mismo tiempo. Sincroniza de nuevo para verlo');
                END IF;
            WHEN OTHERS THEN
                --DATOS MAL FORMADOS (UUID O FECHA INVALIDA) O RECHAZO DE LA FUNCION
                jRESULTADO := json_build_object('CODIGO', 400, 'MENSAJE', SQLERRM);
        END;

        --CLASIFICAR EL RESULTADO
        IF (jRESULTADO ->> 'CODIGO')::INTEGER = 200 AND COALESCE((jRESULTADO -> 'DATOS' ->> 'YA_EXISTIA')::BOOLEAN, false) THEN
            jESTADO := 'YA_EXISTIA';
            jOMITIDOS := jOMITIDOS + 1;
        ELSIF (jRESULTADO ->> 'CODIGO')::INTEGER = 200 THEN
            jESTADO := 'OK';
            jGUARDADOS := jGUARDADOS + 1;
        ELSE
            jESTADO := 'RECHAZADO';
            jRECHAZADOS := jRECHAZADOS + 1;
            LISTA_RECHAZADOS := LISTA_RECHAZADOS || json_build_object('UUID', jREGISTRO ->> 'uuid', 'TIPO', jTIPO, 'OPERACION', jOPERACION, 'MENSAJE', jRESULTADO ->> 'MENSAJE');
        END IF;

        LISTA_RESULTADOS := LISTA_RESULTADOS || json_build_object(
            'UUID', jREGISTRO ->> 'uuid',
            'ORDEN', jREGISTRO -> 'orden',
            'ESTADO', jESTADO,
            'MENSAJE', CASE WHEN jESTADO = 'RECHAZADO' THEN jRESULTADO ->> 'MENSAJE' END);
    END LOOP;

    --DEJAR CONSTANCIA DE LA SINCRONIZACION
    jID_SINCRONIZACION := funcion_Retorna_ultmoid('TAB_SINCRONIZACIONES', 'ID_SINCRONIZACION');
    INSERT INTO TAB_SINCRONIZACIONES (ID_SINCRONIZACION, ID_FINCA, ID_USUARIO, RECIBIDOS_SINCRONIZACION, GUARDADOS_SINCRONIZACION,
        OMITIDOS_SINCRONIZACION, RECHAZADOS_SINCRONIZACION, DETALLE_SINCRONIZACION)
    VALUES (jID_SINCRONIZACION, jID_FINCA, jID_USUARIO, jRECIBIDOS, jGUARDADOS, jOMITIDOS, jRECHAZADOS,
        CASE WHEN jRECHAZADOS > 0 THEN array_to_json(LISTA_RECHAZADOS) END);

    RETORNO := json_build_object('CODIGO', 200,
        'MENSAJE', jGUARDADOS || CASE WHEN jGUARDADOS = 1 THEN ' subido' ELSE ' subidos' END
            || ', ' || jOMITIDOS || CASE WHEN jOMITIDOS = 1 THEN ' ya existía' ELSE ' ya existían' END
            || ', ' || jRECHAZADOS || CASE WHEN jRECHAZADOS = 1 THEN ' rechazado' ELSE ' rechazados' END,
        'DATOS', array_to_json(LISTA_RESULTADOS));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;
